<?php
$title='API Usage & Costs';$subtitle='Every API Setu can use – status, free limits, usage and estimated cost';
$C=Usage::catalog();
if(is_post()){
  $o=jd(setting('usage_prices'));
  foreach(($_POST['svc']??[]) as $k=>$x)if(isset($C[$k]))$o[$k]=['price'=>max(0,(float)($x['price']??0)),'free'=>max(0,(float)($x['free']??0))];
  foreach(($_POST['mdl']??[]) as $k=>$x){$k=trim($k);if($k!==''&&($x['in']!==''||$x['out']!==''))$o['_models'][$k]=['in'=>max(0,(float)$x['in']),'out'=>max(0,(float)$x['out'])];}
  if(($n=trim($_POST['new_model']??''))!=='')$o['_models'][$n]=['in'=>max(0,(float)($_POST['new_in']??0)),'out'=>max(0,(float)($_POST['new_out']??0))];
  Settings::set('usage_prices',je($o));
  Settings::set('fx_mode',($_POST['fx_mode']??'auto')==='manual'?'manual':'auto');
  if(($_POST['usd_rate']??'')!=='')Settings::set('usd_rate',max(0.0001,(float)$_POST['usd_rate']));
  flash('Prices and limits saved.');redirect(url('usage'));}
$M=Usage::month();$P=Usage::prices();$D=Usage::daily(30);
[$rate,$fxm,$fxat]=Usage::fx();$cur=setting('currency','INR');$sym=setting('currency_symbol','₹');
$lc=fn($usd)=>$cur==='USD'?'$'.number_format($usd,2):$sym.number_format($usd*$rate,$usd*$rate<100?2:0);
$usd=fn($v)=>'$'.number_format($v,$v<10?2:0);
$groups=['Maps & website data'=>['google_places','serpapi','pagespeed'],'AI writing'=>['anthropic','web_search','openai','openrouter','gemini','groq','deepseek','custom'],'Messaging'=>['email','whatsapp','whatsapp_api'],'AI voice calls'=>['voice_sarvam','voice_bland','voice_vapi','voice_retell','voice_custom'],'Calendar'=>['gcal']];
$rows=[];$tc=0;$tp=0;$calls=0;$warn=[];
foreach($groups as $g=>$ks)foreach($ks as $k){if(!isset($C[$k]))continue;$c=$C[$k];$m=$M[$k]??null;$price=(float)($P[$k]['price']??$c[3]);$free=(float)($P[$k]['free']??$c[4]);[$b,$bp]=Usage::bill($k,$m,$price,$free);$tc+=$b;$tp+=$bp;$calls+=$m['calls']??0;if($m&&$free>0&&$m['proj']>$free)$warn[]=$c[0];$rows[$g][]=[$k,$c,$m,$price,$free,$b,$bp,Usage::status($k)];}
$fmt=fn($c,$m)=>!$m?'<span class="muted">0</span>':($c[2]==='tokens'?number_format($m['in']/1000,1).'k in · '.number_format($m['out']/1000,1).'k out':number_format($m['units'],$c[2]==='minutes'?1:0).' <small class="muted">'.$c[2].'</small>');
// 30-day chart
$days=[];for($i=29;$i>=0;$i--){$d=date('Y-m-d',strtotime("-$i day"));$days[$d]=['c'=>(float)($D[$d]['cost']??0),'n'=>(int)($D[$d]['calls']??0)];}
$mx=max(0.01,max(array_column($days,'c')));$mn=max(1,max(array_column($days,'n')));$W=900;$H=170;$bw=$W/30;
$svg='<svg class="chart" viewBox="0 0 '.$W.' '.($H+26).'" role="img" aria-label="Daily API usage, last 30 days">';
foreach([0,.5,1] as $g){$y=$H-$g*$H+2;$svg.='<line x1="0" x2="'.$W.'" y1="'.$y.'" y2="'.$y.'" stroke="#EEF0F5"/><text x="2" y="'.($y-4).'" font-size="10" fill="#98A0B3">'.e($usd($mx*$g)).'</text>';}
$i=0;$pts=[];foreach($days as $d=>$v){$h=$v['c']/$mx*($H-14);$x=$i*$bw+4;$svg.='<rect x="'.round($x,1).'" y="'.round($H-$h+2,1).'" width="'.round($bw-8,1).'" height="'.round(max($h,$v['c']>0?2:0),1).'" rx="4" fill="url(#ug)"><title>'.e(date('d M',strtotime($d)).': '.$usd($v['c']).' · '.$v['n'].' calls').'</title></rect>';$pts[]=round($x+($bw-8)/2,1).','.round($H-$v['n']/$mn*($H-14)+2,1);if($i%5===0||$i===29)$svg.='<text x="'.round($x+($bw-8)/2,1).'" y="'.($H+18).'" font-size="10.5" fill="#98A0B3" text-anchor="middle">'.date('d M',strtotime($d)).'</text>';$i++;}
$svg.='<polyline points="'.implode(' ',$pts).'" fill="none" stroke="#F97316" stroke-width="2" stroke-linejoin="round" opacity=".85"/><defs><linearGradient id="ug" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#8B5CF6"/><stop offset="1" stop-color="#6366F1"/></linearGradient></defs></svg>';
$gi=['Maps & website data'=>['map','orange'],'AI writing'=>['spark','violet'],'Messaging'=>['msg','green'],'AI voice calls'=>['mic','pink'],'Calendar'=>['cal','teal']];
$sn=0;
?>
<div class="stats"><?=kpi('Estimated bill this month',$lc($tc),'activity','violet',$usd($tc).' after free tiers')?><?=kpi('Projected by month end',$lc($tp),'target','indigo',$usd($tp).' at the current pace')?><?=kpi('API calls this month',number_format($calls),'zap','sky',count($M).' services used in '.date('F'))?><?=kpi('Free limits at risk',count($warn),'alert',$warn?'rose':'green',$warn?'<span class="dn">'.e(implode(', ',$warn)).'</span>':'all within free limits')?></div>
<?php if($warn):?><div class="al al-warn"><?=icon('alert')?><span><b>Heads-up:</b> at the current pace you will go over the free limit for <?=e(implode(', ',$warn))?> this month. Extra usage is billed at the price shown below.</span></div><?php endif?>
<div class="card compact"><div class="card-h"><h3><span class="hi c-violet"><?=icon('activity')?></span>Last 30 days</h3><div class="row sm muted"><span class="row nw" style="gap:6px"><i style="width:10px;height:10px;border-radius:3px;background:#7C5CF0;display:inline-block"></i>Cost (USD)</span><span class="row nw" style="gap:6px"><i style="width:14px;height:2px;background:#F97316;display:inline-block"></i>Calls</span></div></div><?=$svg?></div>
<form method="post"><?=csrf_field()?>
<div class="card p0"><div class="card-h"><h3><span class="hi c-sky"><?=icon('db')?></span>All APIs – <?=date('F Y')?></h3><div class="row"><span class="muted sm">Edit any free limit or price, then save</span><button class="btn btn-p btn-sm"><?=icon('check')?>Save</button></div></div><div class="tw"><table class="tbl usage-t"><thead><tr><th class="sn">#</th><th>API</th><th>Status</th><th>Used this month</th><th>Free limit</th><th>Price (USD / unit)</th><th class="num">Projected</th><th class="num">Est. cost</th><th class="num">Projected cost</th></tr></thead><tbody>
<?php foreach($rows as $g=>$list):[$gic,$gcl]=$gi[$g];?><tr><td colspan="9" style="background:var(--s);padding-top:9px;padding-bottom:9px" class="c-<?=$gcl?>"><b class="row nw" style="gap:8px;color:var(--c);font-size:12px;text-transform:uppercase;letter-spacing:.06em"><?=icon($gic)?><?=e($g)?></b></td></tr><?php foreach($list as [$k,$c,$m,$price,$free,$b,$bp,[$stl,$stc]]):$sn++;$used=$m?($c[5]==='day'?$m['used']:$m['units']):0;$pc=$free>0?min(999,round($used/$free*100)):null;$cl=$pc===null?'g':($pc>=100?'r':($pc>=75?'a':'g'));$tok=$c[2]==='tokens';?><tr><td class="sn"><?=$sn?></td><td class="biz" style="min-width:210px"><b><?=e($c[0])?></b><small><?=$c[6]?'<a class="lnk" href="'.e($c[6]).'" target="_blank" rel="noopener">Pricing ↗</a> · ':''?><?=e(mb_strimwidth($c[7],0,90,'…'))?></small></td><td><span class="bdg c-<?=$stc?> <?=$stc==='green'?'bdg-dot':''?>"><?=e($stl)?></span></td><td class="nowrap"><?=$fmt($c,$m)?><?php if($m&&$m['errors']):?><small class="red" style="display:block"><?=$m['errors']?> failed</small><?php endif?></td><td style="min-width:170px"><?php if($tok):?><span class="muted sm">Pay per token</span><?php else:?><div class="row nw" style="gap:6px"><input type="number" min="0" step="1" name="svc[<?=$k?>][free]" value="<?=e($free+0)?>" style="width:96px;height:32px;margin:0"><small class="muted">/ <?=$c[5]?></small></div><?php if($free>0&&$m):?><div class="pb <?=$cl?>" style="margin-top:6px"><i style="width:<?=min(100,(int)$pc)?>%"></i></div><small class="pbm"><?=$pc?>% used</small><?php endif?><?php endif?></td><td><?php if($tok):?><a class="lnk sm" href="#models">Per model ↓</a><?php else:?><div class="row nw" style="gap:6px"><input type="number" min="0" step="0.0001" name="svc[<?=$k?>][price]" value="<?=e($price+0)?>" style="width:100px;height:32px;margin:0"><small class="muted">/ <?=e(rtrim($c[2],'s'))?></small></div><?php endif?></td><td class="num nowrap"><?=$m&&!$tok?number_format($m['proj']).($free>0&&$m['proj']>$free?' <span class="bdg c-rose sm">over</span>':''):'<span class="muted">—</span>'?></td><td class="num nowrap"><b><?=$lc($b)?></b><?=$cur!=='USD'&&$b>0?'<small class="muted" style="display:block">'.$usd($b).'</small>':''?></td><td class="num nowrap"><?=$lc($bp)?></td></tr><?php endforeach;endforeach?></tbody></table></div></div>
<div class="g2"><div class="card" id="models"><div class="card-h"><h3><span class="hi c-violet"><?=icon('spark')?></span>AI model prices</h3><span class="muted sm">USD per 1 million tokens</span></div><div class="tw"><table class="tbl"><thead><tr><th>Model</th><th>Input</th><th>Output</th></tr></thead><tbody><?php foreach($P['_models'] as $k=>$x):?><tr><td><code><?=e($k)?></code><?=$k===AI::model()?' <span class="bdg c-green sm">in use</span>':''?></td><td><input type="number" step="0.001" min="0" name="mdl[<?=e($k)?>][in]" value="<?=e($x['in'])?>" style="width:100px;height:32px;margin:0"></td><td><input type="number" step="0.001" min="0" name="mdl[<?=e($k)?>][out]" value="<?=e($x['out'])?>" style="width:100px;height:32px;margin:0"></td></tr><?php endforeach?><tr><td><input name="new_model" placeholder="Add model id" style="height:32px;margin:0"></td><td><input type="number" step="0.001" min="0" name="new_in" style="width:100px;height:32px;margin:0"></td><td><input type="number" step="0.001" min="0" name="new_out" style="width:100px;height:32px;margin:0"></td></tr></tbody></table></div><p class="hint">Unlisted models are still counted (tokens), but their cost shows as $0 until you add a price.</p></div>
<div class="card"><div class="card-h"><h3><span class="hi c-green"><?=icon('refresh')?></span>Currency conversion</h3></div><?php if($cur==='USD'):?><p class="sm muted">Your currency is USD – no conversion needed.</p><?php else:?><div class="ov2" style="grid-template-columns:1fr 1fr"><div class="c-green"><span><?=icon('tag')?>1 USD</span><b><?=$sym.number_format($rate,2)?></b><small><?=$fxm==='auto'?'Live rate · updated '.e($fxat):($fxm==='manual'?'Manual rate':'Rate service unreachable – using saved rate')?></small></div><div class="c-indigo"><span><?=icon('activity')?>This month</span><b><?=$lc($tc)?></b><small><?=$usd($tc)?></small></div></div><label class="mt">Rate source<select name="fx_mode" data-toggle><option value="auto" <?=$fxm!=='manual'?'selected':''?>>Automatic – free exchange-rate API, refreshed daily</option><option value="manual" <?=$fxm==='manual'?'selected':''?>>Manual – I enter the rate</option></select></label><label data-show="fx_mode=manual" class="mb0">1 USD in <?=e($cur)?><input type="number" step="0.0001" name="usd_rate" value="<?=e(setting('usd_rate','84'))?>"></label><?php endif?><p class="hint">Estimates use list prices and your free limits; your provider's invoice is final. Free limits reset on the 1st (or daily where marked).</p><div class="card-f"><button class="btn btn-p"><?=icon('check')?>Save all</button></div></div></div>
</form>
